package com.vignesh.banking.security;
import jakarta.servlet.*;import jakarta.servlet.http.*;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.core.authority.SimpleGrantedAuthority;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.stereotype.Component;import org.springframework.web.filter.OncePerRequestFilter;import java.io.IOException;import java.util.List;
@Component public class JwtAuthFilter extends OncePerRequestFilter{ private final JwtService jwt; public JwtAuthFilter(JwtService j){jwt=j;} protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain) throws ServletException,IOException{ String h=req.getHeader("Authorization"); if(h!=null && h.startsWith("Bearer ")){ String t=h.substring(7); if(jwt.valid(t)){ SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(jwt.extractEmail(t),null,List.of(new SimpleGrantedAuthority("ROLE_"+jwt.extractRole(t))))); } } chain.doFilter(req,res);} }
